  (@cons (list Op) ch_200 (@cons (list Op) ch_201 (@cons (list Op) ch_202 (@nil (list Op))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))).

Local Open Scope nat_scope.

Lemma cert_to_halts (f512 f1024 : nat) (chunks : list (list Op))
  (Hcert : is_halted (execChunksF f512 f1024 chunks
    (st_ok CL (@cons Tok b1 (@nil Tok)) (@nil Tok))) = true) :
  halts tm c0.
Proof.
  rewrite execChunksF_eq in Hcert.
  set (st0 := st_ok CL (@cons Tok b1 (@nil Tok)) (@nil Tok)) in *.
  assert (H0 : ResSound c0 st0) by exact entry_steps.
  destruct (execChunksK f512 f1024 chunks st0) as [? ? ? | |] eqn:Hexec;
    try discriminate Hcert.
  pose proof (execChunksK_sound f512 f1024 chunks H0
    ltac:(rewrite Hexec; discriminate)) as Hsound.
  rewrite Hexec in Hsound.
  exact Hsound.
Qed.

Definition f512_val : nat :=
  N.to_nat (Npos (xO (xO (xO (xO (xO (xO (xO (xO (xO xH)))))))))).
Definition f1024_val : nat :=
  N.to_nat (Npos (xO (xO (xO (xO (xO (xO (xO (xO (xO (xO xH))))))))))).

Lemma cert_ok :
  is_halted (execChunksF f512_val f1024_val all_chunks
    (st_ok CL (@cons Tok b1 (@nil Tok)) (@nil Tok))) = true.
Proof.
  vm_cast_no_check (eq_refl true).
Qed.

Lemma halt_internal : halts tm c0.
Proof.
  exact (cert_to_halts f512_val f1024_val all_chunks cert_ok).
Qed.

End Internal.

Theorem halt : halts tm c0.
Proof. exact Internal.halt_internal. Qed.
